import { useEffect, useRef } from 'react';
import sceneJson from '../data/openingScene.json';

/**
 * The opening title scene: "Ember Gate".
 *
 * A night valley framed by two cliffs, a lit stone arch in the middle, embers rising out of it and the
 * studio wordmark across the sky. The composition - palette, ridge silhouettes, gate geometry, the
 * seeded star and ember fields, and the title lettering as pixel runs - comes from
 * `src/data/openingScene.json`, generated by the Java tool in `tools/scene-forge`, which renders the
 * same frames offline so neither language holds a private copy of the art direction.
 *
 * Two things are browser-only, because they are UI timing rather than art: the reveal of the wordmark
 * (driven by the parent, so it can be skipped) and the fade from black (CSS, in `Opening.tsx`).
 */

type Rgb = [number, number, number];

interface Peak {
  x: number;
  height: number;
  spread: number;
}

interface Layer {
  name: string;
  baseY: number;
  body: number[];
  shade: number[];
  rim: number[];
  parallax: number;
  peaks: Peak[];
}

const SETTINGS = sceneJson.settings;
const W = SETTINGS.width;
const H = SETTINGS.height;
const HORIZON = SETTINGS.horizon;
const FPS = SETTINGS.fps;

/** Parallax period in ms; must match `DRIFT_PERIOD_MS` in `OpeningRenderer.java`. */
const DRIFT_PERIOD_MS = 36000;
const MOON_X = 128;
const MOON_Y = 21;
const MOON_RADIUS = 4;

const toRgb = (color: number[]): Rgb => [color[0], color[1], color[2]];

const PALETTE = {
  skyStops: sceneJson.palette.skyStops.map((stop) => ({ at: stop.at, color: toRgb(stop.color) })),
  moon: toRgb(sceneJson.palette.moon),
  moonHighlight: toRgb(sceneJson.palette.moonHighlight),
  moonHalo: toRgb(sceneJson.palette.moonHalo),
  starCool: toRgb(sceneJson.palette.starCool),
  starWarm: toRgb(sceneJson.palette.starWarm),
  mist: toRgb(sceneJson.palette.mist),
  ember: toRgb(sceneJson.palette.ember),
  emberHot: toRgb(sceneJson.palette.emberHot),
  ground: toRgb(sceneJson.palette.ground),
  groundShade: toRgb(sceneJson.palette.groundShade),
  glyph: toRgb(sceneJson.palette.glyph),
  glyphShadow: toRgb(sceneJson.palette.glyphShadow),
  glyphGlow: toRgb(sceneJson.palette.glyphGlow),
};

const GATE = sceneJson.gate;
const PATH = sceneJson.path;
const LAYERS: Layer[] = sceneJson.layers;
const STARS = sceneJson.stars;
const EMBERS = sceneJson.embers;
const MIST = sceneJson.mist;
const WORDMARK = sceneJson.wordmark;

const clamp01 = (value: number) => Math.max(0, Math.min(1, value));

function mix(a: Rgb, b: Rgb, t: number): Rgb {
  return [
    Math.round(a[0] + (b[0] - a[0]) * t),
    Math.round(a[1] + (b[1] - a[1]) * t),
    Math.round(a[2] + (b[2] - a[2]) * t),
  ];
}

function skyAt(y: number): Rgb {
  const t = clamp01(y / (HORIZON - 1));
  for (let i = 0; i < PALETTE.skyStops.length - 1; i++) {
    const { at, color } = PALETTE.skyStops[i];
    const next = PALETTE.skyStops[i + 1];
    if (t <= next.at) return mix(color, next.color, (t - at) / (next.at - at));
  }
  return PALETTE.skyStops[PALETTE.skyStops.length - 1].color;
}

/** Ridge line of a range at column `x`; identical curve to `RidgeGeometry.top` in Java. */
function ridgeTop(x: number, peaks: Peak[], baseY: number): number {
  let top = baseY + 1;
  for (const p of peaks) {
    const d = Math.abs(x - p.x);
    if (d > p.spread) continue;
    const t = 1 - d / p.spread;
    const y = baseY - Math.round(p.height * Math.sin((t * Math.PI) / 2) ** 1.35);
    if (y < top) top = y;
  }
  return top;
}

function blend(buf: Uint8ClampedArray, x: number, y: number, color: Rgb, alpha: number): void {
  if (x < 0 || y < 0 || x >= W || y >= H || alpha <= 0) return;
  const a = Math.min(1, alpha);
  const i = (y * W + x) * 4;
  buf[i] = Math.round(buf[i] + (color[0] - buf[i]) * a);
  buf[i + 1] = Math.round(buf[i + 1] + (color[1] - buf[i + 1]) * a);
  buf[i + 2] = Math.round(buf[i + 2] + (color[2] - buf[i + 2]) * a);
}

function buildBase(): Uint8ClampedArray {
  const buf = new Uint8ClampedArray(W * H * 4);
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const color = y < HORIZON
        ? skyAt(y)
        : mix(PALETTE.ground, PALETTE.groundShade, (y - HORIZON) / Math.max(1, H - HORIZON - 1));
      const i = (y * W + x) * 4;
      buf[i] = color[0];
      buf[i + 1] = color[1];
      buf[i + 2] = color[2];
      buf[i + 3] = 255;
    }
  }
  return buf;
}

let cachedBase: Uint8ClampedArray | null = null;
let cachedVignette: Float32Array | null = null;
const BASE = () => (cachedBase ??= buildBase());

/** Darkness at the frame edges, precomputed because it never changes. */
function vignetteMask(): Float32Array {
  if (cachedVignette) return cachedVignette;
  const mask = new Float32Array(W * H);
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const nx = Math.abs(x - W / 2) / (W / 2);
      const ny = Math.abs(y - H / 2) / (H / 2);
      const edge = Math.max(0, Math.max(nx, ny) - 0.62) / 0.38;
      mask[y * W + x] = edge * edge * 0.42;
    }
  }
  cachedVignette = mask;
  return mask;
}

function drawStars(buf: Uint8ClampedArray, t: number): void {
  for (const star of STARS) {
    if (star.x < 0 || star.y < 0 || star.x >= W || star.y >= HORIZON) continue;
    const twinkle = 0.5 + 0.5 * Math.sin(t * 0.0016 + star.phase);
    const falloff = 1 - star.y / HORIZON;
    const alpha = (0.22 + 0.62 * twinkle) * (0.45 + falloff * 0.55);
    blend(buf, star.x, star.y, star.warm ? PALETTE.starWarm : PALETTE.starCool, alpha);
  }
}

function halo(buf: Uint8ClampedArray, cx: number, cy: number, radius: number, color: Rgb, strength: number, skyOnly: boolean): void {
  for (let y = Math.floor(cy - radius); y <= Math.ceil(cy + radius); y++) {
    for (let x = Math.floor(cx - radius); x <= Math.ceil(cx + radius); x++) {
      if (x < 0 || y < 0 || x >= W || y >= H) continue;
      if (skyOnly && y >= HORIZON) continue;
      const d = Math.hypot(x - cx, y - cy) / radius;
      if (d >= 1) continue;
      blend(buf, x, y, color, (1 - d) ** (skyOnly ? 2 : 3) * strength);
    }
  }
}

function drawMoon(buf: Uint8ClampedArray): void {
  halo(buf, MOON_X, MOON_Y, MOON_RADIUS + 7, PALETTE.moonHalo, 0.1, true);
  halo(buf, MOON_X, MOON_Y, MOON_RADIUS + 3, PALETTE.moonHalo, 0.16, true);
  const paintDisc = (cx: number, cy: number, radius: number, color: Rgb | null, alpha: number) => {
    for (let y = Math.floor(cy - radius); y <= Math.ceil(cy + radius); y++) {
      for (let x = Math.floor(cx - radius); x <= Math.ceil(cx + radius); x++) {
        if (x < 0 || y < 0 || x >= W || y >= HORIZON) continue;
        if ((x - cx) ** 2 + (y - cy) ** 2 > radius * radius) continue;
        blend(buf, x, y, color ?? skyAt(y), alpha);
      }
    }
  };
  paintDisc(MOON_X, MOON_Y, MOON_RADIUS, PALETTE.moon, 0.96);
  // Bite out of the upper right to leave a crescent, filling with the sky behind it.
  paintDisc(MOON_X + 2.1, MOON_Y - 1.6, MOON_RADIUS * 0.92, null, 1);
  blend(buf, Math.round(MOON_X - 2), Math.round(MOON_Y + 1), PALETTE.moonHighlight, 0.9);
  blend(buf, Math.round(MOON_X - 1), Math.round(MOON_Y + 2), PALETTE.moonHighlight, 0.75);
}

/** Horizontal camera offset for a layer at time `t`, in whole pixels. */
function drift(t: number, parallax: number): number {
  return Math.round(Math.sin((t / DRIFT_PERIOD_MS) * Math.PI * 2) * SETTINGS.drift * parallax);
}

function drawLayer(buf: Uint8ClampedArray, layer: Layer, t: number): void {
  const baseY = Math.round(layer.baseY);
  const body = toRgb(layer.body);
  const shade = toRgb(layer.shade);
  const rim = toRgb(layer.rim);
  const glowMid = toRgb(GATE.glowMid);
  const offset = drift(t, layer.parallax);
  for (let x = 0; x < W; x++) {
    const top = ridgeTop(x - offset, layer.peaks, baseY);
    const span = Math.max(1, baseY - top);
    for (let y = Math.max(0, top); y < Math.min(baseY, H); y++) {
      const depth = (y - top) / span;
      let color = mix(shade, body, Math.min(1, depth * 1.6));
      if (y <= top + 1) color = mix(rim, color, y === top ? 0 : 0.55);
      const spill = Math.max(0, 1 - Math.abs(x - GATE.cx) / 34) * Math.max(0, 1 - depth * 1.2);
      if (spill > 0) color = mix(color, glowMid, spill * 0.16);
      const i = (y * W + x) * 4;
      buf[i] = color[0];
      buf[i + 1] = color[1];
      buf[i + 2] = color[2];
      buf[i + 3] = 255;
    }
  }
}

function drawGate(buf: Uint8ClampedArray, t: number): void {
  const stone = toRgb(GATE.stone);
  const stoneShade = toRgb(GATE.stoneShade);
  const stoneRim = toRgb(GATE.stoneRim);
  const glowCore = toRgb(GATE.glowCore);
  const glowMid = toRgb(GATE.glowMid);
  const glowEdge = toRgb(GATE.glowEdge);
  const cx = GATE.cx;
  const baseY = Math.round(GATE.baseY);
  const radius = GATE.radius;
  const innerRadius = radius - GATE.thickness;
  const archY = baseY - GATE.rise;
  const crownY = archY - radius;
  const pulse = 0.86 + 0.14 * Math.sin(t * 0.0014);

  halo(buf, cx, baseY - 6, radius + 13, glowEdge, 0.11 * pulse, false);

  // Interior: firelight, hot at the floor and violet up at the crown.
  const floorY = baseY - 2;
  for (let y = crownY; y <= baseY; y++) {
    for (let x = cx - radius; x <= cx + radius; x++) {
      const dx = x - cx;
      const inside = Math.abs(dx) < innerRadius && (y > archY || Math.hypot(dx, y - archY) < innerRadius);
      if (!inside) continue;
      const heat = clamp01((floorY - y) / Math.max(1, floorY - crownY));
      const color = heat < 0.45 ? mix(glowCore, glowMid, heat / 0.45) : mix(glowMid, glowEdge, (heat - 0.45) / 0.55);
      const shimmer = 0.92 + 0.08 * Math.sin(t * 0.003 + y * 0.7 + x * 0.3);
      blend(buf, x, y, color, (0.97 - heat * 0.45) * pulse * shimmer);
    }
  }

  // Stone: pillars carrying a half ring, rim-lit inside and shaded outside.
  for (let y = crownY - 1; y < baseY; y++) {
    for (let x = cx - radius; x <= cx + radius; x++) {
      const dx = x - cx;
      const distance = y <= archY ? Math.hypot(dx, y - archY) : Math.abs(dx);
      if (distance > radius || distance < innerRadius) continue;
      let color = stone;
      if (distance <= innerRadius + 1) color = stoneRim;
      else if (distance >= radius - 0.5) color = stoneShade;
      const i = (y * W + x) * 4;
      if (x < 0 || y < 0 || x >= W || y >= H) continue;
      buf[i] = color[0];
      buf[i + 1] = color[1];
      buf[i + 2] = color[2];
      buf[i + 3] = 255;
    }
  }

  // Two footing blocks anchor the gate.
  for (let x = cx - radius - 2; x <= cx + radius + 2; x++) {
    for (let y = baseY; y < Math.min(H, baseY + 2); y++) {
      blend(buf, x, y, y === baseY ? mix(stoneRim, stone, 0.5) : stoneShade, 1);
    }
  }
}

function drawPath(buf: Uint8ClampedArray): void {
  const color = toRgb(PATH.color);
  const edge = toRgb(PATH.edge);
  const top = PATH.topY;
  const bottom = Math.min(PATH.bottomY, H);
  const span = Math.max(1, bottom - top);
  for (let y = top; y < bottom; y++) {
    const t = (y - top) / span;
    const half = PATH.topHalf + (PATH.bottomHalf - PATH.topHalf) * t;
    const cx = Math.round(PATH.cx);
    for (let x = Math.floor(cx - half); x <= Math.ceil(cx + half); x++) {
      const edgeFactor = Math.abs(x - cx) / half;
      let pixel = edgeFactor > 0.86 ? edge : color;
      if ((x + y) % 7 === 0) pixel = mix(pixel, edge, 0.35);
      blend(buf, x, y, pixel, 0.75 + t * 0.2);
    }
  }
}

function drawEmbers(buf: Uint8ClampedArray, t: number): void {
  for (const ember of EMBERS) {
    let cycle = ((t / 1000) * ember.speed + ember.phase) % 1;
    if (cycle < 0) cycle += 1;
    const y = ember.y - cycle * ember.rise;
    const x = ember.x + Math.sin(t * 0.0016 + ember.phase * 6.283) * 1.8;
    const alpha = (1 - cycle) ** 1.5 * 0.95;
    if (alpha <= 0.02) continue;
    const px = Math.round(x);
    const py = Math.round(y);
    const color = cycle < 0.3 ? PALETTE.emberHot : PALETTE.ember;
    blend(buf, px, py, color, alpha);
    blend(buf, px, py - 1, color, alpha * 0.28);
    blend(buf, px + 1, py, color, alpha * 0.22);
    blend(buf, px - 1, py, color, alpha * 0.22);
  }
}

function drawMist(buf: Uint8ClampedArray, t: number): void {
  for (const band of MIST) {
    const y0 = Math.round(band.y);
    const rows = Math.round(band.thickness);
    const color = toRgb(band.color);
    for (let i = 0; i < rows; i++) {
      const y = y0 + i;
      if (y < 0 || y >= H) continue;
      const shape = Math.sin((Math.PI * (i + 1)) / (rows + 1));
      for (let x = 0; x < W; x++) {
        const wave = 0.55 + 0.45 * Math.sin(x * 0.075 + t * 0.0009 * band.speed + y * 0.35);
        blend(buf, x, y, color, band.alpha * shape * wave);
      }
    }
  }
}

/**
 * How far a single letter has appeared, 0..1.
 *
 * Letters start in order, each one overlapping the next slightly, and the whole word is settled by
 * `reveal === 0.72` so the last beat of the intro is a held title rather than a still-moving one.
 */
export function letterAlpha(reveal: number, index: number): number {
  const spread = 0.055;
  const ramp = 0.16;
  return clamp01((reveal - index * spread) / ramp);
}

/** Extra brightness for the letter that just landed, so the reveal reads as light, not a wipe. */
export function letterFlash(reveal: number, index: number): number {
  const spread = 0.055;
  const ramp = 0.16;
  const local = clamp01((reveal - index * spread) / ramp);
  return local > 0 && local < 1 ? 1 - local : 0;
}

export function drawWordmark(buf: Uint8ClampedArray, reveal: number): void {
  WORDMARK.letters.forEach((letter, index) => {
    const alpha = letterAlpha(reveal, index);
    if (alpha <= 0) return;
    const flash = letterFlash(reveal, index);
    const color = mix(PALETTE.glyph, PALETTE.glyphGlow, flash * 0.8);
    for (const [rx, ry, rw, rh] of letter.runs) {
      for (let y = letter.y + ry; y < letter.y + ry + rh; y++) {
        for (let x = letter.x + rx; x < letter.x + rx + rw; x++) {
          if (x < 1 || y < 1 || x >= W - 1 || y >= H - 1) continue;
          blend(buf, x, y + 1, PALETTE.glyphShadow, 0.55 * alpha);
          blend(buf, x + 1, y + 1, PALETTE.glyphShadow, 0.35 * alpha);
          blend(buf, x, y, PALETTE.glyphGlow, 0.16 * alpha + flash * 0.25);
          blend(buf, x, y, color, alpha);
        }
      }
    }
  });
}

/** One complete frame of the opening scene at time `t` with the wordmark revealed by `reveal`. */
export function openingFrame(t: number, reveal = 1): Uint8ClampedArray {
  const buf = new Uint8ClampedArray(BASE());
  drawStars(buf, t);
  drawMoon(buf);
  for (const layer of LAYERS) drawLayer(buf, layer, t);
  drawGate(buf, t);
  drawPath(buf);
  drawEmbers(buf, t);
  drawMist(buf, t);

  const mask = vignetteMask();
  const dark: Rgb = [3, 3, 8];
  for (let i = 0; i < mask.length; i++) {
    if (mask[i] <= 0) continue;
    blend(buf, i % W, Math.floor(i / W), dark, mask[i]);
  }

  // The title goes on last, so the dark edges of the frame never dim the lettering.
  drawWordmark(buf, reveal);
  return buf;
}

export function OpeningScene({ reveal }: { reveal: number }) {
  const ref = useRef<HTMLCanvasElement | null>(null);
  const revealRef = useRef(reveal);
  revealRef.current = reveal;

  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const image = ctx.createImageData(W, H);
    const paint = (t: number, progress: number) => {
      image.data.set(openingFrame(t, progress));
      ctx.putImageData(image, 0, 0);
    };

    const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;
    if (reduce) {
      paint(9000, 1);
      return;
    }

    let raf = 0;
    let lastDraw = -Infinity;
    const start = performance.now();
    const tick = (now: number) => {
      raf = requestAnimationFrame(tick);
      if (document.visibilityState === 'hidden') return;
      if (now - lastDraw < 1000 / FPS) return;
      lastDraw = now;
      paint(now - start, revealRef.current);
    };
    paint(0, revealRef.current);
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, []);

  return (
    <canvas
      ref={ref}
      width={W}
      height={H}
      className="opening-canvas"
      role="img"
      aria-label="Pixel-art night valley with a lit stone gate and the Pixelarium wordmark"
    />
  );
}
